import { z } from 'zod';

// Form validation schema with relations
export const plandetailFormSchema = z.object({
  planId: z.number().int().positive(),
  locationCode: z.string().trim().min(1, 'Location Code is required').max(50, 'Location Code must be 50 characters or less').regex(/^[\w-]+$/, 'Location Code can only contain letters, numbers, underscores and dashes'),
  locationType: z.string().trim().max(50, 'Location Type must be 50 characters or less').optional(),
  productCode: z.string().trim().min(1, 'Product Code is required').max(50, 'Product Code must be 50 characters or less').regex(/^[\w-]+$/, 'Product Code can only contain letters, numbers, underscores and dashes'),
  productSubCode: z.string().trim().max(100, 'Product Sub Code must be 100 characters or less').regex(/^[\w-]*$/, 'Product Sub Code can only contain letters, numbers, underscores and dashes').optional(),
  plannedQuantity: z.number().int().min(0),
  actualQuantity: z.number().int().min(0).optional(),
  plannedStartDate: z.union([z.string(), z.date()]).optional(),
  plannedEndDate: z.union([z.string(), z.date()]).optional(),
  actualStartDate: z.union([z.string(), z.date()]).optional(),
  actualEndDate: z.union([z.string(), z.date()]).optional(),
  status: z.string().trim().max(50, 'Status must be 50 characters or less').optional(),
  priority: z.number().int().min(1).max(10).optional(),
  note: z.string().trim().optional(),
});

// Create plandetail schema (same as form + ownerId)
export const createPlanDetailSchema = plandetailFormSchema.extend({
  ownerId: z.string().min(1, 'Owner ID is required'),
});

