// List parameters validation
export const plandetailListParamsSchema = z.object({
  page: z.number().int().min(1).default(1),
  limit: z.number().int().min(1).max(100).default(10),
  search: z.string().trim().max(255).optional(),
  planCode: z.string().trim().max(255).optional(),
  productCode: z.string().trim().max(255).optional(),
  productName: z.string().trim().max(255).optional(),
  sortBy: z.enum(['createdAt', 'updatedAt', 'productSubCode', 'locationCode']).default('createdAt'),
  sortOrder: z.enum(['asc', 'desc']).default('desc'),
  showAll: z.boolean().default(false),
  includeRelations: z.boolean().default(false),
});

// Export parameters validation
export type PlanDetailExportParams = z.infer<typeof plandetailListParamsSchema>;

